int process_gif_image(struct iwgifrcontext* rctx) {
    if (!rctx) {
        return 0;
    }

    // Read image header
    if (fread(&rctx->image_descriptor, sizeof(rctx->image_descriptor), 1, rctx->file) != 1) {
        return 0;
    }

    // Validate image dimensions
    if (rctx->image_descriptor.width <= 0 || rctx->image_descriptor.height <= 0) {
        return 0;
    }

    // Initialize color tables if present
    if (rctx->image_descriptor.has_local_color_table) {
        size_t color_table_size = (1U << (1 + rctx->image_descriptor.color_table_depth)) * sizeof(uint32_t);
        if (color_table_size > SIZE_MAX) {
            return 0;
        }

        rctx->local_color_table = malloc(color_table_size);
        if (!rctx->local_color_table) {
            return 0;
        }

        if (fread(rctx->local_color_table, sizeof(uint32_t), (1U << (1 + rctx->image_descriptor.color_table_depth)), rctx->file) != (1U << (1 + rctx->image_descriptor.color_table_depth))) {
            free(rctx->local_color_table);
            rctx->local_color_table = NULL;
            return 0;
        }
    }

    // Handle transparency
    if (rctx->image_descriptor.is_transparent) {
        if (rctx->image_descriptor.transparent_index >= (1U << (1 + rctx->image_descriptor.color_table_depth))) {
            return 0;
        }

        // Modify the color table to mark the transparent index
        if (rctx->local_color_table) {
            ((uint32_t*)rctx->local_color_table)[rctx->image_descriptor.transparent_index] |= 0x10000000; // Mark as transparent
        }
    }

    // Read LZW code size
    if (fread(&rctx->lzw_code_size, sizeof(rctx->lzw_code_size), 1, rctx->file) != 1) {
        return 0;
    }

    // Validate LZW code size
    if (rctx->lzw_code_size < 2 || rctx->lzw_code_size > 12) {
        return 0;
    }

    // Initialize screen context
    rctx->current_line = 0;
    rctx->pixels_remaining = rctx->image_descriptor.width * rctx->image_descriptor.height;

    // Read pixel data in subblocks
    while (rctx->pixels_remaining > 0) {
        uint8_t subblock_size;
        if (fread(&subblock_size, sizeof(subblock_size), 1, rctx->file) != 1) {
            return 0;
        }

        if (subblock_size == 0) {
            break;
        }

        if (subblock_size > 255) {
            return 0;
        }

        uint8_t subblock[256];
        if (fread(subblock, sizeof(uint8_t), subblock_size, rctx->file) != subblock_size) {
            return 0;
        }

        // Process subblock with LZW decoding
        if (!lzw_decode(rctx, subblock, subblock_size)) {
            return 0;
        }
    }

    return 1;
}
